  setTimeout(() => {
    res.end();
  }, 10_000);
});

app.get('/delay/json', (request, res) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  setTimeout(() => {
    res.end();
  }, 10_000);
});

